'use strict';
/* ===== SCR-00, 01, 08, 09, 10, 15, 16, 17, 18 ===== */
DEV.a4b = { w: 794, h: 1123, n: 'A4 portrait — page 2 (PRINT)' };
const prePl = (w, fn) => { w.ui = {}; fn(w); };
const bw = (w, ctx) => ctx.W;
function briefMap(w, h, o = {}) { return mapSVG(Object.assign({ w, h, vb: [60, 380, 760, 760 * h / w], L: { pois: false }, route: 'none', hill: true }, o)); }

/* ---- SCR-00 boot error ---- */
defScreen({ id: 'SCR-00', name: 'Boot error', route: '(boot failure only)', mode: 'ops', tier: 'T0', frs: 'FR-16, NFR-10', states: [['single', 'Single']], sizes: ['proj', 'evaPhoneL'], preset: (w) => { w.ui = {}; },
  render: (w, ctx) => `<div class="big-empty cgrid" style="height:100%;padding:32px" data-ann="id:SCR-00|note:Plain-language cause, missing asset name, Retry, run instructions. Quiet: only the failure uses status colour"><i class="reg" style="left:12px;top:12px"></i><i class="reg" style="right:12px;top:12px"></i><i class="reg" style="left:12px;bottom:12px"></i><i class="reg" style="right:12px;bottom:12px"></i>
    <span class="code">[ SCR-00 /// BOOT ]</span>${status('warning', { slot: 'boot', word: 'CANNOT START' })}<h2 class="ttl" style="font-size:28px">A required file is missing</h2>
    <div class="cut cut-s fill-raised" style="padding:12px 16px;text-align:left;max-width:560px"><div class="kv" style="grid-template-columns:110px 1fr"><span class="lbl">WHAT HAPPENED</span><span>The map data failed its check, so the planner cannot load.</span><span class="lbl">MISSING FILE</span><span class="mono">grid/comm_hab.u8 <span class="t3">(02 §C.5 L11)</span></span><span class="lbl">DATA VERSION</span><span class="mono">${esc(FX.site.data_version)}</span></div></div>
    <div class="row" style="gap:10px">${btn('Retry', { kind: 'primary', size: 'tall', act: 'noop', icon: 'rot' })}${btn('Run instructions', { size: 'tall', act: 'noop', icon: 'file' })}</div><span class="t3" style="max-width:52ch;font-size:13px">Fix the deployment (rebuild the site data) and retry. Nothing is guessed: no layer is shown without its file.</span></div>` });

/* ---- SCR-01 mission briefing (BRIEF) ---- */
function statSlab(num, label, note, extra = '') { return `<div class="stat cut cut-m sig" style="--fill:var(--signal);--line:var(--signal)"><span class="sv">${num}</span><span class="micro" style="color:var(--on-signal)">${label}</span><span style="font-size:12px;color:var(--on-signal)">${note}</span>${extra}</div>`; }
function renderBrief(w, ctx) {
  const W = ctx.W, wide = W >= 1100, small = W < 480, st = w.ui.s1 || 'ready';
  const hero = `<div class="slab cut cut-l" style="--fill:var(--p-charcoal);--line:var(--p-charcoal);position:relative;min-height:${wide ? 330 : 190}px;overflow:hidden;padding:0"><div style="position:absolute;inset:0;filter:grayscale(1) contrast(1.1)">${st === 'loading' ? '' : briefMap(wide ? 700 : W - 40, wide ? 330 : 190, { vb: [60, 400, 700, wide ? 330 : 190] })}</div><i class="reg" style="left:12px;top:12px;color:#fff"></i><i class="reg" style="right:12px;top:12px;color:#fff"></i><i class="reg" style="left:12px;bottom:36px;color:#fff"></i>
    <span class="micro" style="position:absolute;left:14px;bottom:10px;color:#fff;background:#000a;padding:2px 6px">SCHEMATIC — not HiRISE imagery · real basemap after TASK-01/03 · credit NASA/JPL/UArizona/USGS (TODO verify)</span>${st === 'loading' ? '<div class="skel" style="position:absolute;left:24px;top:24px;width:60%"></div><span class="code" style="position:absolute;left:24px;top:44px;color:#fff">Loading manifest…</span>' : ''}</div>`;
  const head = `<div style="padding:${small ? '16px 0' : '24px 0'}"><h1 class="disp" style="font-size:${small ? 38 : wide ? 72 : 52}px;line-height:.98;margin:0;font-weight:500">Plan the walk.<br>Survive the storm.</h1><span class="code" style="display:block;margin-top:10px;color:var(--text-2)">EXPLORATION ZONE 01-A</span></div>`;
  const slab = `<div class="cut cut-l sig" style="--fill:var(--signal);--line:var(--signal);padding:${small ? 16 : 28}px;display:flex;flex-direction:column;gap:14px;min-height:${wide ? 330 : 0}px"><div class="row" style="justify-content:space-between"><span class="micro" style="color:var(--on-signal)">GALE / MT SHARP</span><span class="micro" style="color:var(--on-signal)">SOL ${N('sol', { chip: false, unit: false, size: 12 })}</span></div>
    <p style="font:400 15px/1.6 var(--f-mono);margin:0;color:var(--on-signal)">One EZ, two crew, one storm. Every number traced to NASA and ESA data.</p><div class="sp"></div><div class="row" style="gap:10px;flex-wrap:wrap">${btn('Start planning ▸', { act: 'goto', data: { arg: 'scr-02' }, kind: 'primary', size: 'tall', cls: 'dk' })}${btn('Run demo', { act: 'goto', data: { arg: 'demo' }, size: 'tall' })}${btn('Open demo plan', { act: 'goto', data: { arg: 'scr-02-results-ok' }, size: 'tall' })}</div></div>`;
  const stats = `<div style="display:grid;grid-template-columns:${wide ? 'repeat(3,1fr) 1.2fr' : small ? '1fr' : 'repeat(3,1fr)'};gap:12px">${statSlab(N('stat_missions', { chip: 'g', unit: false, size: 56 }), 'MARS MISSIONS', 'NASA + ESA: MRO, Mars Express, MGS, Odyssey, MSL, MAVEN, TGO')}${statSlab(N('stat_types', { chip: 'g', unit: false, size: 56 }), 'STOP TYPES', 'SCI / RES / ENG (01 §A.4)')}${statSlab(N('event_total', { chip: 'g', size: 40 }), 'RAD, 20 MAY 2024', 'REPLAYED published total (01 FR-37)')}
    <div class="cut cut-m" style="--fill:var(--bg);--line:var(--unknown);border-style:dashed;padding:14px;font-size:13px;${wide ? '' : 'grid-column:1/-1'}"><span class="micro">DISCLAIMER · 01 §F.1</span><p class="serif" style="font-size:14px;line-height:1.5;margin:4px 0 0">${esc(FX.meta.disclaimer)}</p></div></div>`;
  const nav = `<div class="row" style="justify-content:space-between;padding:12px 20px;border-bottom:1px solid var(--hairline)"><span class="row" style="gap:8px"><svg viewBox="0 0 24 24" width="22" height="22"><path d="M7 2h10l5 5v10l-5 5H7l-5-5V7Z" fill="var(--signal)"/></svg><b class="disp" style="font-size:16px">Marswalk</b></span><span class="row" style="gap:8px">${btn('Join as ▸', { size: 'sm', act: 'goto', data: { arg: 'scr-10' } })}${btn('Sources →', { size: 'sm', act: 'goto', data: { arg: 'scr-09' } })}</span></div>`;
  return `<div class="brief" style="height:100%;overflow:auto" data-ann="id:SCR-01|token:paper · concrete · signal · ink|note:BRIEF fluid 360–1920. One accent per view: signal orange. Chrome neutral; imagery carries colour (04 §B.3 P5)">${nav}<div style="padding:${small ? 14 : 24}px;display:flex;flex-direction:column;gap:${small ? 14 : 24}px"><div style="display:grid;grid-template-columns:${wide ? '1.35fr 1fr' : '1fr'};gap:${wide ? 24 : 14}px">${hero}${wide ? slab : ''}</div>${head}${!wide ? slab : ''}${stats}</div></div>`;
}
defScreen({ id: 'SCR-01', name: 'Mission briefing', route: '#/', mode: 'brief', tier: 'T0', frs: 'FR-01, 15', states: [['loading', 'Loading'], ['ready', 'Ready']], sizes: ['b1440', 'b768', 'b360'], note: 'Boot error → SCR-00. Loading and Ready are the two normal states.', preset: (w, s) => { w.ui = { s1: s }; }, render: renderBrief });

/* ---- SCR-09 sources & methods (BRIEF) ---- */
function renderSources(w, ctx) {
  const W = ctx.W, two = W >= 900, small = W < 480, sec = (id, t, body) => `<section id="${id}" style="margin:0 0 28px"><h2 class="disp" style="font-size:${small ? 22 : 28}px; margin:0 0 10px">${t}</h2>${body}</section>`;
  const sp = s => `<div class="cut cut-m" style="--fill:var(--panel);padding:0 0 10px;margin-bottom:12px" id="${s.layer ? 'layer-' + s.layer : s.id}"><i class="stripe"></i><div style="padding:8px 14px 0" class="row"><span class="code">[ ${s.code} ]</span><span class="code">${esc(s.id)}</span></div><div style="padding:2px 14px"><b class="disp" style="font-size:17px">${esc(s.title)}</b></div>
    <div class="kv" style="padding:6px 14px 0;grid-template-columns:${small ? '90px' : '120px'} 1fr"><span class="lbl">PUBLISHER</span><span>${esc(s.publisher)}</span><span class="lbl">MISSIONS</span><span>${esc(s.missions || '—')} · ${esc(s.instr || '—')}</span><span class="lbl">VERSION</span><span>${/TODO|PLACEHOLDER/.test(s.version) ? PH(s.version, 'TASK-04') : esc(s.version)}</span>${s.res ? `<span class="lbl">RESOLUTION</span>${N(s.res, { chip: 'g', size: 14 })}` : ''}<span class="lbl">CREDIT</span><span>${esc(s.credit)}</span><span class="lbl">LICENCE</span><span>${/TODO/.test(s.licence) ? PH(s.licence, 'TASK-04') : esc(s.licence)}</span><span class="lbl">ACCESSED</span><span class="mono">${s.acc}</span>${s.note ? `<span class="lbl">NOTE</span><span>${esc(s.note)}</span>` : ''}${s.url ? `<span class="lbl">LINK</span><span class="mono" style="font-size:11px;word-break:break-all"><a href="${esc(s.url)}" target="_blank" rel="noopener">${esc(s.url)}</a></span>` : ''}<span class="lbl">SPEC</span><span class="mono t3">${esc(s.src)}</span></div></div>`;
  const par = (id, ti, ps) => sec(id, ti, ps.map(p => `<p class="serif" style="margin:0 0 12px;font-size:${small ? 16 : 17}px">${p}</p>`).join(''));
  const eq = t => `<pre class="cut cut-s" style="--fill:var(--panel);padding:10px 14px;font:500 13px/1.5 var(--f-mono);white-space:pre-wrap;margin:0 0 12px">${esc(t)}</pre>`;
  const ps = FX.param_sets.map(p => `<tr><td><b>${esc(p.title)}</b><br><span class="code">${p.param_set_id}</span></td><td>${p.values.map(v => `${esc(v[0])}: ${N(v[1], { chip: 'g', size: 13 })}`).join('<br>')}</td><td>${chip(p.provenance)}<br><span style="font-size:12px">${esc(p.note)}</span></td></tr>`).join('');
  const toc = ['Datasets', 'Processing', 'Models', 'Assumptions (ParamSets)', 'Replay sources', 'Limitations', 'AI use', 'Diagnostics'];
  const content = par('datasets', 'Datasets', ['Every layer and computed value carries a provenance class and a link here. Credit goes to NASA, USGS and ESA. <b>ESA Mars Express HRSC</b> is inside the USGS Gale merged DEM; <b>ESA TGO</b> trajectory kernels give the relay geometry; Solar Orbiter (ESA/NASA) is the source of the flare-class estimate for 20 May 2024.']).replace('</section>', FX.sources.map(sp).join('') + '</section>') +
    par('processing', 'Processing', ['The source DEM is equirectangular with standard parallel 0°. It is reprojected to a local equirectangular projection on the IAU_2015:49900 sphere (radius 3,396,190 m, east-positive longitude), because at about 4.75°S the source x-scale overstates east–west ground distance by 0.343 %. Mars coordinates never pass through EPSG:3857 or WGS84 code paths.', 'Slope is computed on the 1 m posts and aggregated to a 5 m routing grid (slope_p90, slope_max). Thermal inertia is sampled on its own 100 m grid. Hab-mast line of sight is a viewshed over the 5 m grid with curvature drop d²/2R.']) +
    par('models', 'Models', ['<b>Walking time</b> uses a Tobler-based speed scaled to 3.3 km/h on flat ground (assumed, Apollo 17 planning value). <b>Background radiation</b> is a measured rate multiplied by the planned duration, labelled simplified.', eq('dose_mSv = rate_mSv_per_day × duration_h / 24      (02 §D.4)'), '<b>Time to haven</b> is the minimum of walking to the hab and a rendezvous with the pressurized rover, plus 5 minutes ingress (assumed).', eq('haven(p) = min( T_hab(p) + t_ingress , min_q max(T_crew(q), T_veh(q)) + t_ingress )   (02 §D.8)'), '<b>Event dose</b> integrates the replayed surface rate with an assumed shielding factor per location (suit 1.0, pressurized rover 0.6, hab 0.4; physical shielding is not modelled).']) +
    sec('assumptions', 'Assumptions (ParamSets)', `<table class="tbl" style="font-size:13px"><tr><th>Set</th><th>Values</th><th>Provenance</th></tr>${ps}</table>`) +
    par('replay', 'Replay sources', ['The 20 May 2024 solar particle event is a real historical record <b>replayed</b> on a simulated mission clock; it is not a live feed from Mars. The RAD dose curve is “replayed — Curiosity RAD, 20 May 2024”; its time series is not yet archived for this build (U-15), so the chart shape is a placeholder.']) +
    par('limits', 'Limitations', ['Radio coverage is line-of-sight only: no Fresnel zone, diffraction or multipath. Sun elevation ignores terrain shadowing, refraction and dust. Low thermal inertia is read as “possible loose fines”, an assumed interpretation (A-05). Slope limits, speeds, consumables and shelter values are illustrative assumptions.']) +
    par('ai', 'AI use', [esc(FX.meta.ai_use) + ' Coding assistants used to build the system are disclosed in docs/AI_USE.md.']) +
    sec('diag', 'Diagnostics', `<div class="kv" style="grid-template-columns:140px 1fr"><span class="lbl">DATA VERSION</span><span class="mono">${esc(FX.site.data_version)}</span><span class="lbl">CHECKSUMS</span>${PH('not checked in the prototype', 'TASK-14')}<span class="lbl">FIXTURE</span><span class="mono">${esc(FX.meta.fixture_version)}</span></div>`);
  return `<div class="brief" style="height:100%;overflow:auto;padding:${small ? 14 : 28}px" data-ann="id:SCR-09|note:Long-form uses Source Serif 4 (P7); dataset entries are specimen cards with DS codes matching DataSource ids (P1, P3)"><div style="display:grid;grid-template-columns:${two ? '200px 1fr' : '1fr'};gap:28px"><nav aria-label="Index" style="${two ? 'position:sticky;top:0;align-self:start' : ''}"><span class="micro">INDEX</span><ul style="margin-top:6px;display:flex;flex-direction:${two ? 'column' : 'row'};gap:6px;flex-wrap:wrap">${toc.map((t, i) => `<li><a href="#${['datasets', 'processing', 'models', 'assumptions', 'replay', 'limits', 'ai', 'diag'][i]}" style="font-size:14px">${t}</a></li>`).join('')}</ul></nav><div style="min-width:0"><span class="code" style="color:var(--text-2)">[ SCR-09 /// SOURCES & METHODS ]</span><h1 class="disp" style="font-size:${small ? 32 : 52}px;margin:4px 0 20px;font-weight:500">Sources & methods</h1>${content}</div></div></div>`;
}
defScreen({ id: 'SCR-09', name: 'Sources & methods', route: '#/sources', mode: 'brief', tier: 'T0', frs: 'FR-15', states: [['default', 'Default']], sizes: ['b1440', 'b768', 'b360'], preset: (w) => { w.ui = {}; }, render: renderSources });

/* ---- SCR-10 join / role select (BRIEF) ---- */
function renderJoin(w, ctx) {
  const W = ctx.W, s = w.ui.s10 || 'ready', roles = [['planner', 'Planner', 'Place stops, check constraints, publish the plan.', 'T0'], ['ops', 'Ops', 'Run the clock, watch crew, approve options.', 'T1'], ['eva:EV1', 'EV1', 'Suit tablet and HUD: next stop, haven, summon, abort.', 'T1'], ['eva:EV2', 'EV2', 'Second suit tablet (or ops-only simulation).', 'T1'], ['earth', 'Earth', 'Delayed telemetry and messages through the relay queue.', 'T2']];
  const tile = ([k, n, d, t]) => `<div class="cut cut-m" style="--fill:var(--panel);padding:14px;display:flex;flex-direction:column;gap:8px;min-height:150px;position:relative"><span class="code">[ ${k.toUpperCase()} ]</span><b class="disp" style="font-size:24px">${n}</b>${t === 'T2' ? '<span class="tag t2s" style="align-self:flex-start">T2 SCOPE</span>' : ''}<span style="font-size:14px">${d}</span><div class="sp"></div>${s === 'taken' && k === 'eva:EV1' ? `<div class="errtxt">${sicon('caution')}<span>EV1 is connected on another device — take over?</span></div><div class="row" style="gap:6px">${btn('Take over', { size: 'sm', kind: 'primary', act: 'noop' })}${btn('Pick another role', { size: 'sm', act: 'noop' })}</div>` : btn('Join ▸', { size: 'sm', act: 'noop', disabled: s === 'connecting' || s === 'unreach', kind: 'primary' })}</div>`;
  const stat = s === 'connecting' ? `${status('advisory', { slot: 'join', word: 'CONNECTING' })}<span>Connecting to hab…</span>` : s === 'unreach' ? `${status('warning', { slot: 'join', word: 'UNREACHABLE' })}<span>Hab Core unreachable — see SCR-18</span>` : `${status('nominal', { slot: 'join', word: 'READY' })}<span>Session ${PH('s-####', 'TASK-20')} · ${FX.scenario.scenario_id} · clock ${N('speed', { chip: 'g', size: 14 })}</span>`;
  return `<div class="brief" style="height:100%;overflow:auto;padding:${W < 480 ? 14 : 28}px" data-ann="id:SCR-10|note:Five role tiles; the ops console shows a QR per role; a device remembers its role for the session only"><span class="code" style="color:var(--text-2)">[ SCR-10 /// JOIN ]</span><h1 class="disp" style="font-size:${W < 480 ? 34 : 56}px;font-weight:500;margin:4px 0 14px">Join as</h1>
    <div class="row" style="gap:12px;padding:10px 14px;margin-bottom:16px;border:1px solid var(--edge)"><span class="micro">[ HAB CORE ]</span>${stat}</div><div style="display:grid;grid-template-columns:repeat(auto-fill,minmax(${W < 480 ? 240 : 210}px,1fr));gap:14px">${roles.map(tile).join('')}</div>${s === 'unreach' ? `<div class="cut cut-s" style="--fill:var(--panel);--line:var(--warning);padding:12px;margin-top:16px"><b>Connecting to hab… ${PH('http://##.##.##.##:####', 'TASK-28')}</b><div class="t2" style="font-size:13px">Check the router; retry; or use single-laptop mode.</div></div>` : ''}</div>`;
}
defScreen({ id: 'SCR-10', name: 'Join / role select', route: '#/join', mode: 'brief', tier: 'T1', frs: 'FR-30, 31', states: [['connecting', 'Connecting'], ['ready', 'Ready'], ['taken', 'Role taken'], ['unreach', 'Hab Core unreachable']], sizes: ['b1440', 'b768', 'b360'], preset: (w, s) => { w.ui = { s10: s }; }, render: renderJoin });

/* ---- print helpers ---- */
function printBar(fid) { return `<div class="noprint" style="position:absolute;right:18px;top:12px;display:flex;gap:6px;z-index:5">${btn('Print', { size: 'sm', act: 'print', icon: 'print', data: { fid } })}</div>`; }
ACT.print = (el, c) => { const fr = c.fr; if (!fr) return; try { document.body.classList.add('printing'); fr.wrap.classList.add('print-target'); window.print(); } catch (e) { } finally { document.body.classList.remove('printing'); fr.wrap.classList.remove('print-target'); } };
const phs = (txt, why) => PH(txt, why);
/* ---- SCR-08 briefing card (PRINT, one A4) ---- */
function renderBriefing(w, ctx) {
  const s = w.ui.s8 || 'ok', ok = s === 'ok', part = s === 'partial', over = s === 'over', pub = w.ui.pub;
  const banner = part ? `<div class="cut cut-s" style="--fill:var(--warning);--line:var(--warning);color:#fff;padding:8px 12px;font:700 14px var(--f-ui)">${sicon('warning', 'onfill')} Plan incomplete — not valid for use</div>` : over ? `<div class="cut cut-s" style="--fill:var(--bg);--line:var(--caution);padding:8px 12px;font:700 13px var(--f-ui)">${status('caution', { slot: 'banner', word: 'OVER LIMITS' })} <span style="font-weight:500">Exceeded: segment in darkness (sun below horizon)</span></div>` : '';
  const val = (k, o = {}) => part ? '<span class="num t3" data-provenance="modelled" title="totals omitted: plan incomplete">—</span>' : N(k, Object.assign({ chip: 'g', size: 15 }, o));
  const stopsRows = STOPS.map(x => `<tr><td class="mono">${x.n}</td><td>${x.code}<br><span class="t3">${STOPN[x.n].name ? esc(STOPN[x.n].name) : 'name TBD'}</span></td><td>${N('p_ltst_start', { chip: 'g', size: 12, unit: false })} / ${PH('##:##', 'TASK-06')}</td><td>${N('p_dwell', { chip: 'g', size: 12 })}</td><td>${N('p_sunel', { chip: 'g', size: 12 })}</td><td style="font-size:11px">${x.n === 2 ? 'Resource — ISRU water' : x.n === 3 ? 'Science — boxwork' : 'Engineering — terrain'}</td></tr>`).join('');
  const prof = `<div>${profileSVG({}, 714, 56, part ? 'partial' : 'ok')}</div>`;
  const tl = (sid, crew) => FX.tasks.list.filter(t => t.stop === sid && t.crew_id === crew).map(t => `${t.kind} — ${esc(t.text)}`).join('<br>');
  const tasksTbl = `<div><span class="mod">STOP TASKS (FR-50) ${chip('assumed', 'g', 'team-authored, PROPOSED copy')}</span><table class="tbl tight" style="font-size:10px;margin-top:2px"><tr><th>Stop</th><th>EV1</th><th>EV2</th></tr>${TSTOPS.map(sid => `<tr><td class="mono">${STOPN[tStopNo(sid)].code}</td><td>${tl(sid, 'EV1')}</td><td>${tl(sid, 'EV2')}</td></tr>`).join('')}</table></div>`;
  return `<div class="print"><div class="pg" data-ann="id:SCR-08|px:A4 portrait, 12 mm margins|note:Header · map + metrics · stops table · profile · warnings + assumptions · footer. Patterns kept for B/W printers">${printBar(ctx.fid)}
    <div class="row" style="justify-content:space-between;border-bottom:2px solid #111827;padding-bottom:6px"><div><span class="code">[ SCR-08 /// BRIEFING CARD ]</span><div class="disp" style="font-size:24px">Marswalk — plan “demo plan”</div></div><div class="kv" style="grid-template-columns:80px auto;font-size:11px"><span class="lbl">SITE</span><span>${esc(FX.site.site_id)}</span><span class="lbl">DATA</span><span class="mono">${esc(FX.site.data_version)}</span><span class="lbl">HASH</span>${N('p_hash', { chip: 'g', size: 11, unit: false })}<span class="lbl">GENERATED</span>${PH('####-##-##T##:##Z', 'TASK-11')}</div></div>${banner}
    <div style="display:grid;grid-template-columns:60% 1fr;gap:12px;flex:none"><div class="mapbox" style="height:235px;border:1px solid #111827">${briefMap(430, 235, { vb: [150, 480, 640, 350], route: part ? 'partial' : 'ok', L: { comm: true, pois: true }, stops: STOPS.map(x => ({ n: x.n, x: x.p[0], y: x.p[1], code: x.code })), poiLabels: false })}<span class="maptag">SCHEMATIC — not real terrain</span></div>
      <div class="col" style="gap:8px"><div>${part ? status('warning', { slot: 'card', word: 'PARTIAL' }) : over ? status('caution', { slot: 'card', word: 'OVER LIMITS' }) : status('nominal', { slot: 'card', word: 'PLAN OK' })}</div>${[['Distance', 'p_dist'], ['Walk time', 'p_walk'], ['EVA total', 'p_total'], ['Max slope', 'p_maxslope'], ['Max walkback', 'p_walkback'], ['Dose (solar max)', 'p_dose']].map(([l, k]) => `<div class="row" style="justify-content:space-between;border-bottom:1px solid var(--hairline)"><span class="lbl">${l}</span>${val(k)}</div>`).join('')}</div></div>
    <table class="tbl" style="font-size:12px"><tr><th>#</th><th>Stop</th><th>Arrive UTC / LTST</th><th>Dwell</th><th>Sun elev</th><th>Notes</th></tr>${stopsRows}</table>${tasksTbl}${prof}
    <div style="display:grid;grid-template-columns:1fr 1fr;gap:12px"><div><span class="mod">WARNINGS</span><ul style="font-size:12px;margin-top:4px"><li class="row" style="gap:6px;align-items:flex-start">${status('caution', { slot: 'card-w', word: 'CAUTION' })}<span>Slope 12.6° exceeds caution 10° for 80 m (05 §F.3)</span></li>${part ? `<li class="row" style="gap:6px;margin-top:4px">${status('warning', { slot: 'card-w', word: 'BLOCKED' })}<span>No feasible route on leg 2</span></li>` : ''}${over ? `<li class="row" style="gap:6px;margin-top:4px">${status('caution', { slot: 'card-w', word: 'CAUTION' })}<span>Segment in darkness</span></li>` : ''}</ul></div>
      <div><span class="mod">ASSUMPTIONS</span><div class="t2" style="font-size:12px;margin-top:4px">Suited ${N('speed_suit', { chip: 'g', size: 12 })} · hard/caution slope ${N('slope_hard', { chip: 'g', size: 12, unit: false })}/${N('slope_caut', { chip: 'g', size: 12 })} · walkback ${N('p_walkback_lim', { chip: 'g', size: 12 })} · haven rule ${N('haven_rule', { chip: 'g', size: 12 })} · dwell ${N('dwell_def', { chip: 'g', size: 12 })}. Defaults are assumptions — not flight rules.</div></div></div>
    <div class="noprint row" style="gap:8px;flex-wrap:wrap">${btn(pub ? 'Published to Hab Core ✓' : ico('ul') + 'Publish to Hab Core', { act: 'publish', size: 'tall', kind: 'primary', data: { fid: ctx.fid }, disabled: part })}${btn('Export plan JSON', { act: 'planJson', size: 'tall', data: { fid: ctx.fid } })}${btn('Back to map', { act: 'goto', data: { arg: 'scr-02' }, size: 'tall' })}${pub ? `<span class="row" style="gap:6px">${status('nominal', { slot: 'publish', word: 'PUBLISHED' })} <span style="font-size:12px">PUBLISH_PLAN ok · plan_revision ${N('rev_ph', { chip: 'g', size: 12, unit: false })} · hash ${N('p_hash', { chip: 'g', size: 12, unit: false })}</span></span>` : ''}${part ? '<span class="errtxt">Publishing is disabled: plan incomplete</span>' : ''}</div>
    ${w.ui.json ? `<pre style="font:11px/1.4 var(--f-mono);background:#F3F4F6;padding:8px;overflow:auto;max-height:200px;margin:0">${esc(planJson())}</pre>` : ''}
    <div class="sp"></div><div style="border-top:1px solid #111827;padding-top:6px;font-size:10.5px;color:var(--text-2)">Sources: USGS Gale merged DEM 1 m (DS—01), USGS orthophoto 25 cm (DS—02), THEMIS thermal inertia (DS—03), MSL RAD (DS—04). Credit NASA, USGS Astrogeology, ESA (Mars Express HRSC inside the DEM). ${esc(FX.meta.disclaimer)}</div></div></div>`;
}
function planJson() { const n = k => FX.nums[k].v; return JSON.stringify({ export_schema_version: '1.0.0', app_version: '0.1.0', site_id: FX.site.site_id, data_version: FX.site.data_version, plan_hash: n('p_hash'), scenario: { eva_start_utc: '2026-11-14T08:00:00Z', max_eva_duration_h: n('p_limit'), dwell_min_per_stop: n('p_dwell'), hard_slope_limit_deg: n('slope_hard'), caution_slope_deg: n('slope_caut'), walkback_limit_km: n('p_walkback_lim'), suited_flat_speed_kmh: n('speed_suit'), solar_phase: 'max', loop: true, max_haven_min: n('haven_rule') }, result: { status: 'OK', totals: { distance_m: n('p_dist'), walk_time_min: n('p_walk'), eva_total_min: n('p_total'), max_slope_deg: n('p_maxslope'), max_walkback_km: n('p_walkback') }, radiation: { dose_mSv: n('p_dose'), dose_low_mSv: n('p_dose_lo'), dose_high_mSv: n('p_dose_hi') } }, disclaimer: 'Exploratory planning prototype — not validated for operations. Values illustrative (05 §F.3).' }, null, 1); }
ACT.publish = (el, c) => { const w = c.w; w.ui.pub = 'sending'; touch(w); setTimeout(() => { w.ui.pub = true; touch(w); }, 700); };
ACT.planJson = (el, c) => { c.w.ui.json = !c.w.ui.json; touch(c.w); };
defScreen({ id: 'SCR-08', name: 'Briefing card', route: '#/briefing', mode: 'print', tier: 'T0', frs: 'FR-14, 15', states: [['ok', 'OK'], ['over', 'Over limits'], ['partial', 'Partial']], sizes: ['a4'], note: 'Includes <b>Publish to Hab Core</b> (PUBLISH_PLAN, 03 SCR-08 v2). Downloads are blocked in the hosted prototype, so Export plan JSON previews the file inline.', preset: (w, s) => { w.ui = { s8: s }; }, render: renderBriefing });

/* ---- SCR-17 post-EVA report (PRINT, 2 pages) ---- */
function renderReport(w, ctx) {
  const p2 = ctx.dev === 'a4b';
  const slab = (k, l, n) => `<div class="cut cut-m" style="--fill:var(--slab);--line:var(--slab);color:var(--on-slab);padding:12px 14px;display:flex;flex-direction:column;gap:4px;min-height:104px"><span style="font-size:30px;line-height:1">${n}</span><span class="micro" style="color:var(--slab-2)">${l}</span></div>`;
  const page1 = `<div class="row" style="justify-content:space-between;border-bottom:2px solid #111827;padding-bottom:6px"><div><span class="code">[ SCR-17 /// POST-EVA REPORT ]</span><div class="disp" style="font-size:24px">Storm at sol 4190 — what happened</div></div><span class="code">p. 1 / 2</span></div>
    <div style="display:grid;grid-template-columns:repeat(4,1fr);gap:10px">${slab('d', 'DOSE RECEIVED VS UNSHELTERED', `${N('r_recv', { chip: 'g', size: 22, unit: false })} <span style="font-size:14px">vs</span> ${N('r_unsh', { chip: 'g', size: 22 })}`)}${slab('t', 'TIME TO SHELTER', N('r_tshel', { chip: 'g', size: 26 }))}${slab('s', 'STOPS COMPLETED', N('r_stops', { chip: 'g', size: 26, unit: false }))}${slab('r', 'PLAN REVISIONS', `REV ${N('plan_rev', { chip: 'g', size: 26, unit: false })} → ${N('rev_ph', { chip: 'g', size: 26, unit: false })}`)}</div>
    <div><span class="mod">PLANNED VS ACTUAL</span><table class="tbl" style="font-size:12px;margin-top:4px"><tr><th>Phase</th><th>Planned</th><th>Actual</th></tr>${['EGRESS', 'STOP 1 · EZ—ENG 01', 'STOP 2 · EZ—RES 02', 'STOP 3 · EZ—SCI 01 (dropped)', 'INGRESS'].map(r => `<tr><td>${r}</td><td>${N('ltst_ph', { chip: 'g', size: 12, unit: false })}</td><td>${N('ltst_ph', { chip: 'g', size: 12, unit: false })}</td></tr>`).join('')}</table></div>
    <div><span class="mod">ALERTS AND RESPONSES</span><table class="tbl" style="font-size:12px;margin-top:4px"><tr><th>Level</th><th>Alert</th><th>Raised → ack → sheltered</th></tr>${[['warning', 'RADIATION_ALERT', 'ltst_alert'], ['caution', 'COMM_SHADOW', 'ltst_ph'], ['advisory', 'EARTH_FORECAST', 'ltst_ph']].map(([l, c, t]) => `<tr><td>${status(l, { slot: 'report' })}</td><td>${esc(FX.alerts[c].text)}</td><td>${N(t, { chip: 'g', size: 12, unit: false })} → ${N('ack_t', { chip: 'g', size: 12, unit: false })} → ${N('r_resp', { chip: 'g', size: 12, unit: false })}</td></tr>`).join('')}</table></div>
    <div><span class="mod">MAP TRACE (30 s decimated, 05 U-24)</span><div class="mapbox" style="height:300px;border:1px solid #111827;margin-top:4px">${briefMap(714, 300, { vb: [150, 500, 620, 260], route: 'ok', loop: false, L: { comm: true }, stops: STOPS.map(x => ({ n: x.n, x: x.p[0], y: x.p[1] })), pr1Path: true, rdv: true, veh: [{ id: 'PR1', x: SCH.rdv[0], y: SCH.rdv[1] }] })}<span class="maptag">SCHEMATIC — not real terrain</span></div></div>`;
  const page2 = `<div class="row" style="justify-content:space-between;border-bottom:2px solid #111827;padding-bottom:6px"><span class="code">[ SCR-17 /// EVENT LOG AND SOURCES ]</span><span class="code">p. 2 / 2</span></div>
    <div><span class="mod">STOP TASKS — DONE / SKIPPED / DROPPED (FR-50) ${chip('simulated', 'g', 'declared scenario state')}</span><table class="tbl" style="font-size:12px;margin-top:4px"><tr><th>Stop</th><th>EV1</th><th>EV2</th></tr>${TSTOPS.map(sid => { const f = crew => { const k = tKeys(w, crew, sid); return `${cN(k[0], { size: 12 })} / ${cN(k[1], { size: 12 })} / ${cN(k[2], { size: 12 })}`; }; return `<tr><td>${STOPN[tStopNo(sid)].code}${STOPN[tStopNo(sid)].name ? ' · ' + esc(STOPN[tStopNo(sid)].name) : ''}</td><td class="mono">${f('EV1')}</td><td class="mono">${f('EV2')}</td></tr>`; }).join('')}</table><span class="t2" style="font-size:11px">Dropped: open tasks closed when the rendezvous option revised the plan (the current stop was cut short and stop 3 was dropped).</span></div>
    <table class="tbl" style="font-size:12px"><tr><th>seq</th><th>time</th><th>actor</th><th>event</th><th>provenance</th></tr>${FX.log.map(r => `<tr><td>${N(r.seq, { chip: false, size: 12, unit: false })}</td><td>${N(r.t, { chip: false, size: 12, unit: false })}</td><td>${esc(r.actor)}</td><td>${esc(r.kind)} — ${esc(r.text)}</td><td>${chip(r.prov, 'full')}</td></tr>`).join('')}</table>
    <div class="kv" style="grid-template-columns:120px 1fr"><span class="lbl">LOG HASH</span>${N('log_hash', { chip: 'g', size: 13, unit: false })}<span class="lbl">SCENARIO</span><span class="mono">${FX.scenario.scenario_id} · seed ${N(FX.scenario.seed, { chip: 'g', size: 12, unit: false })} · ${esc(FX.scenario.data_version)}</span></div>
    <div><span class="mod">SOURCES</span><ul style="font-size:12px;margin-top:4px">${FX.sources.map(s => `<li><span class="code">${s.code}</span> ${esc(s.title)} — ${esc(s.credit)}</li>`).join('')}</ul></div>
    <div class="t2" style="font-size:11.5px">Credit: NASA/JPL-Caltech (MSL RAD, Curiosity), NASA CCMC (DONKI), NASA NAIF (SPICE), USGS Astrogeology (DEM, orthophoto, THEMIS), ESA (Mars Express HRSC, ExoMars TGO kernels). ${esc(FX.meta.disclaimer)}</div>`;
  return `<div class="print"><div class="pg" data-ann="id:SCR-17|px:A4 · 2 pages · 12 mm margins|note:Page 1: four stat slabs, planned vs actual, alerts, map trace. Page 2: event log and sources. Patterns kept for B/W">${printBar(ctx.fid)}${p2 ? page2 : page1}<div class="sp"></div><div class="noprint row" style="gap:8px">${btn('Export log JSON', { act: 'noop', size: 'sm' })}${btn('Back to ops', { act: 'goto', data: { arg: 'scr-11' }, size: 'sm' })}</div></div></div>`;
}
defScreen({ id: 'SCR-17', name: 'Post-EVA report', route: '#/report', mode: 'print', tier: 'T1', frs: 'FR-46', states: [['default', 'Default']], sizes: ['a4', 'a4b'], note: 'Two A4 pages. Most numbers are PLACEHOLDERS until the scenario runs (TASK-21/22); task counts are declared scenario states (FR-50).', preset: (w) => { w.ui = {}; tasksLoad(w, 'final'); }, render: renderReport });

/* ---- SCR-18 hab link lost / connecting (overlay) ---- */
function renderLink(w, ctx) {
  const s = w.ui.s18 || 'lostEva', ops = ctx.W >= 1000;
  const vals = `<div class="dashedbox cut cut-s" style="padding:6px 10px;display:flex;gap:18px;flex-wrap:wrap;--fill:var(--panel)"><div><span class="lbl">HAVEN (CACHED)</span><div style="font-size:${ops ? 36 : 48}px">${N('haven_ev1', { grey: true, size: ops ? 36 : 48 })}</div></div><div><span class="lbl">O₂ (CACHED)</span><div style="font-size:${ops ? 36 : 48}px">${N('o2_ev1', { grey: true, size: ops ? 36 : 48 })}</div></div><div><span class="lbl">AGE</span><div style="font-size:${ops ? 36 : 48}px">${N('stale_age', { chip: 'g', size: ops ? 36 : 48, unit: false })}</div></div></div>`;
  if (s === 'connecting') return `<div class="big-empty cgrid" style="height:100%;padding:24px"><span class="code">[ SCR-18 /// CONNECTING ]</span>${status('advisory', { slot: 'overlay', word: 'CONNECTING' })}<h2 class="ttl" style="font-size:26px">Connecting to hab…</h2><span class="mono" style="font-size:16px">${PH('http://##.##.##.##:####', 'TASK-28')}</span><div class="skel" style="width:260px"></div><span class="t2" style="max-width:48ch;font-size:14px">Check the router, then retry. Single-laptop mode is the fallback.</span><div class="row" style="gap:8px">${btn('Retry', { size: 'tall', kind: 'primary', act: 'noop', icon: 'rot' })}${btn('Single-laptop mode', { size: 'tall', act: 'noop' })}</div></div>`;
  const banner = s === 'restored' ? `<div class="alertbar" data-level="advisory" data-status="advisory" data-slot="overlay" role="status" aria-live="polite" style="position:relative;height:64px">${sicon('advisory', 'onfill')}<span class="atext">Reconnected — replaying missed events</span><span class="mono" style="font-size:13px">seq ${N('seq', { chip: 'g', size: 13, unit: false })}</span></div>` : `<div class="alertbar" data-level="caution" data-status="caution" data-slot="overlay" role="alert" aria-live="assertive" style="position:relative;height:64px">${sicon('caution', 'onfill')}<span class="atext">${ops ? 'Hab server unreachable — retry' : 'HAB SERVER UNREACHABLE — showing cached plan'}</span><span class="mono" style="font-size:14px">reconnect ${N('reconn', { chip: 'g', size: 14, unit: false })} s</span></div>`;
  if (s === 'lostOps') return `<div style="height:100%;display:flex;flex-direction:column;background:var(--bg)">${banner}<div class="big-empty cgrid" style="flex:1"><span class="code">[ SCR-18 /// HAB CORE LOST ]</span><h2 class="ttl" style="font-size:34px">Hab Core is not answering</h2><span class="t2" style="max-width:54ch;font-size:16px">No server heartbeat for ${N('hb_loss', { chip: 'g', size: 16 })}; the server sends one every ${N('hb_ping', { chip: 'g', size: 16 })}. Crew keep their cached plan. Restart the Hab Core: it resumes from session.jsonl.</span>${vals}<div class="row">${btn('Retry', { size: 'tall', kind: 'primary', act: 'noop', icon: 'rot' })}</div></div></div>`;
  return `<div style="height:100%;display:flex;flex-direction:column;background:var(--bg)">${banner}<div style="padding:12px;display:flex;flex-direction:column;gap:10px;flex:1;overflow:hidden"><span class="code">[ SCR-18 /// ${s === 'restored' ? 'RESTORED' : 'LINK LOST'} ] · cached plan, values aged</span>${vals}<div class="cut cut-s fill-raised" style="padding:8px 12px"><span class="lbl">CACHED PLAN</span><div style="font-size:16px">Stop 1 · EZ—ENG 01 → Stop 2 · Hydrated sulfate ledge → Stop 3 · Boxwork ridge</div></div><div class="spacer sp"></div><div class="row" style="gap:8px">${btn('Summon rover', { size: 'xl', kind: 'crit-c', icon: 'pr', act: 'noop' })}<span class="holdnote">Queued — sends when link returns</span></div></div></div>`;
}
defScreen({ id: 'SCR-18', name: 'Hab link lost / connecting', route: '(overlay, all live roles)', mode: 'ops', tier: 'T1', frs: 'FR-16, 32, NFR-13', states: [['connecting', 'Connecting at load'], ['lostEva', 'Lost mid-EVA (EVA)'], ['lostOps', 'Lost (ops)'], ['restored', 'Reconnected']], sizes: ['evaPhoneL', 'proj'], note: 'Distinct from a <i>simulated</i> comm shadow (FR-42), which shows a caution bar instead. Trigger: no heartbeat for 3 s.', preset: (w, s) => { w.ui = { s18: s }; }, render: (w, ctx) => renderLink(w, ctx) });

/* ---- SCR-15 rover tasking (T2) ---- */
function renderRover(w, ctx) {
  const s = w.ui.s15 || w.rover || 'choosing', land = ctx.orient === 'landscape', tiles = [['SCOUT', 'ur'], ['CARRY', 'hand'], ['RELAY', 'ant'], ['RETURN', 'hab']], task = w.ui.task || 'RELAY';
  const stat = { choosing: ['advisory', 'CHOOSING'], confirm: ['caution', 'CONFIRM'], queued: ['advisory', 'QUEUED'], enroute: ['advisory', 'EN ROUTE'], done: ['nominal', 'DONE'], failed: ['warning', 'FAILED'] }[s];
  const map = `<div class="mapbox" style="height:100%;min-height:120px;border:1px solid var(--edge)">${mapSVG({ w: land ? 330 : 366, h: land ? 190 : 250, vb: [320, 520, 440, land ? 253 : 300], L: { comm: true }, route: 'ok', loop: false, stops: STOPS.map(x => ({ n: x.n, x: x.p[0], y: x.p[1] })), veh: [{ id: 'UR1', x: s === 'enroute' ? 520 : SCH.hab[0], y: s === 'enroute' ? 680 : SCH.hab[1] }], rdv: task === 'RELAY', crew: [{ id: 'EV1', x: SCH.s2[0], y: SCH.s2[1], hdg: 40 }] })}<span class="maptag">SCHEMATIC — not real terrain</span><span class="micro" style="position:absolute;left:6px;top:6px;background:var(--bg);padding:2px 6px">${task === 'RELAY' ? 'SUGGESTION: nearest ridge for relay' : 'Tap the map to pick a target'}</span></div>`;
  const tl = `<div style="display:grid;grid-template-columns:1fr 1fr;gap:8px">${tiles.map(([t, ic]) => `<span class="cutw" style="display:flex">${`<button class="btn xl ${t === task ? 'on' : ''}" style="width:100%" data-act="rvTask" data-arg="${t}" aria-pressed="${t === task}">${glyph(ic)}${t}</button>`}</span>`).join('')}</div>`;
  const sum = `<div class="cut cut-s fill-raised" style="padding:8px 12px"><div class="kv" style="grid-template-columns:110px 1fr"><span class="lbl">TASK</span><b>${task}</b><span class="lbl">ETA</span>${N('ur_eta', { chip: 'g', size: 16 })}<span class="lbl">BATTERY AFTER</span>${N('ur_battery', { chip: 'g', size: 16 })}</div></div>`;
  const act = s === 'failed' ? `<div class="errtxt" style="font-size:15px">${sicon('warning')}<span>Task failed — NO_ROUTE: the rover cannot reach that target</span></div>${btn('Pick another target', { act: 'rvSet', data: { arg: 'choosing' }, size: 'xl' })}` : s === 'done' ? `<div class="row">${status('nominal', { slot: 'rover', word: 'DONE' })}<span>Comm-shadow caution clears on the remaining route</span></div>` : s === 'enroute' ? `<div class="row">${status('advisory', { slot: 'rover', word: 'EN ROUTE' })}<span>UR1 driving — ETA ${N('ur_eta', { chip: 'g', size: 15 })}</span></div>` : s === 'queued' ? `<div class="row">${status('advisory', { slot: 'rover', word: 'QUEUED' })}<span>Queued — sends when link returns</span></div>` :
    holdBtn({ key: `${ctx.fid}-task`, wid: ctx.wid, fid: ctx.fid, label: s === 'confirm' ? `Confirm ${task}` : `Send UR1 — ${task}`, icon: 'ur', kind: 'crit-c', act: 'rvSend', outcome: 'UR1 tasked — ETA ##', size: 'xl' });
  return `<div class="eva ${land ? 'l' : 'p'}" style="padding:10px 12px;gap:8px" data-ann="id:SCR-15|note:Goal-level commands only (no joystick). Hold-to-confirm. T2."><div class="row" style="gap:8px">${btn(ico('left') + 'Back', { size: 'sm', act: 'rvBack' })}<b class="ttl" style="font-size:18px">Task rover UR1</b>${t2tag()}<span class="sp"></span>${status(stat[0], { slot: 'rover-state', word: stat[1] })}</div>
    <div style="flex:1;min-height:0;display:grid;gap:8px;grid-template-columns:${land ? '300px 1fr 240px' : '1fr'};grid-template-rows:${land ? '1fr' : 'auto 1fr auto auto'}">${tl}<div style="min-height:0">${map}</div><div class="col" style="gap:8px">${sum}<div class="sheet-f" style="padding:0;border:0">${act}</div></div></div></div>`;
}
ACT.rvTask = (el, c) => { c.w.ui.task = el.dataset.arg; touch(c.w); }; ACT.rvSet = (el, c) => { c.w.ui.s15 = el.dataset.arg; c.w.rover = el.dataset.arg; touch(c.w); }; ACT.rvBack = (el, c) => { if (c.fr && c.fr.prev) c.fr.switchTo('SCR-12'); else if (c.fr) c.fr.switchTo('SCR-12'); };
HOLDACT.rvSend = (w) => { w.ui.s15 = w.ui.s15 === 'confirm' ? 'queued' : 'enroute'; w.rover = w.ui.s15; touch(w); setTimeout(() => { if (w.ui.s15 === 'enroute') { w.ui.s15 = 'done'; w.rover = 'done'; touch(w); } }, 2500); };
defScreen({ id: 'SCR-15', name: 'Rover tasking', route: '(from SCR-12 / SCR-11)', mode: 'ops', tier: 'T2', frs: 'FR-41', states: [['choosing', 'Choosing'], ['confirm', 'Confirm'], ['queued', 'Queued'], ['enroute', 'En route'], ['done', 'Done'], ['failed', 'Failed']], sizes: ['evaPhoneL', 'evaPhoneP'], orientToggle: true, ev: true, note: 'Tier 2 — built at full fidelity, but only after the Tier 1 exit criteria (01 §C.3).', preset: (w, s) => { w.ui = { s15: s, task: s === 'failed' ? 'SCOUT' : 'RELAY' }; w.rover = s; }, render: renderRover });

/* ---- SCR-16 Earth view (T2) ---- */
function renderEarth(w, ctx) {
  const s = w.ui.s16 || 'link', q = w.ui.q || [], black = s === 'blackout', wait = s === 'wait';
  const stamp = `as of ${N('asof_ph', { chip: 'g', size: 13, unit: false })} (${N('light_time', { chip: 'g', size: 13, unit: false })} ago)`;
  const ban = black ? `<div class="alertbar" data-level="caution" data-status="caution" data-slot="earth" style="position:relative">${sicon('caution', 'onfill')}<span class="atext">Conjunction blackout — messages queue until the link returns</span></div>` : wait ? `<div class="alertbar" data-level="advisory" data-status="advisory" data-slot="earth" style="position:relative">${sicon('advisory', 'onfill')}<span class="atext">Waiting for relay pass — next pass MRO in ${N('next_pass', { chip: 'g', size: 16 })}</span></div>` : '';
  const known = black ? `<div class="t2">${status('unknown', { slot: 'earth', word: 'NO DATA' })} <span style="margin-left:8px">Last known state is not shown during conjunction</span></div>` : `<div class="kv" style="grid-template-columns:90px 1fr"><span class="lbl">EV1</span><span>haven ${N('haven_ev1', { chip: 'g', size: 15 })} · O₂ ${N('o2_ev1', { chip: 'g', size: 15 })} <span class="t3">${stamp}</span></span><span class="lbl">EV2</span><span>${N('haven_ev2', { chip: 'g', size: 15 })} <span class="t3">${stamp}</span></span><span class="lbl">ALERT</span><span>${status('warning', { slot: 'earth-a' })} ${esc(FX.alerts.RADIATION_ALERT.text)} <span class="t3">${stamp}</span></span></div>`;
  return `<div class="planner" style="padding:0" data-ann="id:SCR-16|note:Delayed crew and alert summary with “as of” stamps; composer; outgoing queue with delivery estimates. T2">${ban}<div style="flex:1;padding:14px;display:grid;grid-template-columns:1fr 1fr;gap:12px;min-height:0;overflow:auto;position:relative"><div class="col" style="gap:10px"><div class="row"><span class="code">[ SCR-16 /// EARTH VIEW ]</span>${t2tag()}</div>${panel({ code: '[ ORBITAL /// DELAYED TELEMETRY ]', body: known })}${panel({ code: '[ ORBITAL /// EARTH LINK ]', body: `<div class="kv" style="grid-template-columns:110px 1fr"><span class="lbl">LIGHT TIME</span>${N('light_time', { chip: 'full', size: 15, unit: false })}<span class="lbl">NEXT PASS</span><span>MRO ${N('next_pass', { chip: 'full', size: 15 })}</span><span class="lbl">MODEL</span><span class="t2">simplified DTN model (02 §D.12)</span></div>` })}</div>
    <div class="col" style="gap:10px">${panel({ code: '[ ORBITAL /// COMPOSER ]', body: `<div class="field"><span class="lbl">MESSAGE TO MARS</span><textarea data-inp="msg" rows="3" class="inp" style="height:auto;padding:8px;font:14px var(--f-ui);width:100%;resize:none" aria-label="Message to Mars">SEP event in progress. Recommend shelter.</textarea></div><div style="margin-top:8px">${btn('Send via relay queue', { act: 'earthSend', kind: 'primary', size: 'tall', icon: 'ul' })}</div>` })}${panel({ code: '[ ORBITAL /// OUTGOING QUEUE ]', body: q.length ? q.map(m => `<div class="row cut cut-s fill-raised" style="padding:6px 10px;margin-bottom:6px;gap:8px;align-items:flex-start">${status('advisory', { slot: 'queue', word: 'QUEUED' })}<span style="font-size:13px;flex:1">${esc(m)}<br><span class="t3">delivery est. ${N('asof_ph', { chip: 'g', size: 12, unit: false })} (pass + light time ${N('light_time', { chip: 'g', size: 12, unit: false })})</span></span></div>`).join('') : '<span class="t3">Nothing queued. Everything sent waits for the next pass (FR-43).</span>' })}</div></div></div>`;
}
ACT.earthSend = (el, c) => { const t = c.fr.el.querySelector('textarea'); const m = (t && t.value.trim()) || 'Message'; c.w.ui.q = (c.w.ui.q || []).concat(m); touch(c.w); };
defScreen({ id: 'SCR-16', name: 'Earth view', route: '#/earth', mode: 'ops', tier: 'T2', frs: 'FR-43, 48', states: [['link', 'Link available'], ['wait', 'Waiting for relay pass'], ['blackout', 'Conjunction blackout']], sizes: ['proj1280', 'proj'], preset: (w, s) => { w.ui = { s16: s }; }, render: renderEarth });
